#include "nlsql.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

#define NLSQL_MAX_TABLES 256u
#define NLSQL_MAX_COLS 2048u
#define NLSQL_MAX_FKS 2048u
#define NLSQL_MAX_RULES 256u
#define NLSQL_MAX_PARAMS 128u
#define NLSQL_MAX_CHILDREN 32u
#define NLSQL_NAME 128u

typedef struct { char schema[NLSQL_NAME], name[NLSQL_NAME]; unsigned flags; } table_t;
typedef struct { char schema[NLSQL_NAME], table[NLSQL_NAME], name[NLSQL_NAME]; nlsql_type type; unsigned flags; } col_t;
typedef struct { char fs[NLSQL_NAME], ft[NLSQL_NAME], fc[NLSQL_NAME], ts[NLSQL_NAME], tt[NLSQL_NAME], tc[NLSQL_NAME]; } fk_t;
typedef struct { char schema[NLSQL_NAME], table[NLSQL_NAME]; } allow_t;
typedef struct { char schema[NLSQL_NAME], table[NLSQL_NAME], col[NLSQL_NAME]; } deny_t;
typedef struct { char schema[NLSQL_NAME], table[NLSQL_NAME], col[NLSQL_NAME]; } tenant_t;
typedef struct { char name[NLSQL_NAME]; nlsql_type type; nlsql_param_source source; } param_t;

struct nlsql_context { nlsql_config cfg; };
struct nlsql_schema { nlsql_context *ctx; size_t nt, nc, nf; table_t tables[NLSQL_MAX_TABLES]; col_t cols[NLSQL_MAX_COLS]; fk_t fks[NLSQL_MAX_FKS]; };
struct nlsql_schema_builder { nlsql_context *ctx; nlsql_schema *schema; };
struct nlsql_policy { nlsql_context *ctx; size_t na, nd, ntenant; allow_t allow[NLSQL_MAX_RULES]; deny_t deny[NLSQL_MAX_RULES]; tenant_t tenant[NLSQL_MAX_RULES]; size_t max_limit, max_joins; char runtime_name[NLSQL_NAME]; nlsql_type runtime_type; };
struct nlsql_compile_result { nlsql_status status; char *sql, *ir, *manifest, *error; size_t sql_len, nparams; param_t params[NLSQL_MAX_PARAMS]; nlsql_risk risk; unsigned complexity; };

typedef struct node node_t;
struct node { char *atom; size_t off; node_t *child[NLSQL_MAX_CHILDREN]; size_t nchild; };
typedef struct { const char *s; size_t n, p, nodes; nlsql_context *ctx; } parser_t;
typedef struct { char schema[NLSQL_NAME], table[NLSQL_NAME], alias[NLSQL_NAME]; } source_t;
typedef struct { char *s; size_t n, cap; nlsql_context *ctx; } buf_t;

static void cp(char *d, size_t cap, const char *s) { size_t n = s ? strlen(s) : 0u; if (n >= cap) n = cap - 1u; if (cap) { memcpy(d, s, n); d[n] = 0; } }
static int eqs(const char *a, const char *b) { return a && b && strcmp(a,b)==0; }
static int ident(const char *s) { size_t i, n; if (!s || !*s) return 0; n=strlen(s); if (n>=NLSQL_NAME || !(isalpha((unsigned char)s[0]) || s[0]=='_')) return 0; for(i=1;i<n;i++) if (!(isalnum((unsigned char)s[i]) || s[i]=='_' || s[i]=='.')) return 0; return 1; }
static int add_size(size_t a,size_t b,size_t *o){if(b>SIZE_MAX-a)return 0;*o=a+b;return 1;}
static int buf_init(buf_t *b,nlsql_context *c){b->cap=256;b->n=0;b->ctx=c;b->s=(char*)calloc(1,b->cap);return b->s!=NULL;}
static int buf_need(buf_t*b,size_t add){size_t need,cap;char*p;if(!add_size(b->n,add,&need)||!add_size(need,1,&need)||need>b->ctx->cfg.limits.max_sql_bytes)return 0;if(need<=b->cap)return 1;cap=b->cap;while(cap<need){if(cap>SIZE_MAX/2)return 0;cap*=2;}p=(char*)realloc(b->s,cap);if(!p)return 0;b->s=p;b->cap=cap;return 1;}
static int buf_put(buf_t*b,const char*s){size_t n=strlen(s);if(!buf_need(b,n))return 0;memcpy(b->s+b->n,s,n);b->n+=n;b->s[b->n]=0;return 1;}
static int buf_ch(buf_t*b,char c){if(!buf_need(b,1))return 0;b->s[b->n++]=c;b->s[b->n]=0;return 1;}
static int buf_ident(buf_t*b,const char*s,nlsql_dialect d){const char *q=(d==NLSQL_DIALECT_MYSQL)?"`":(d==NLSQL_DIALECT_SQLSERVER?"[":"\"");const char *r=(d==NLSQL_DIALECT_SQLSERVER?"]":q);size_t i;if(!ident(s)||!buf_put(b,q))return 0;for(i=0;s[i];i++){if(s[i]=='.'){if(!buf_put(b,r)||!buf_ch(b,q[0]))return 0;}else if(s[i]==q[0]||s[i]==']'){if(!buf_ch(b,s[i])||!buf_ch(b,s[i]))return 0;}else if(!buf_ch(b,s[i]))return 0;}return buf_put(b,r);}

const char *nlsql_status_name(nlsql_status s){switch(s){case NLSQL_OK:return "OK";case NLSQL_E_INVALID_ARGUMENT:return "INVALID_ARGUMENT";case NLSQL_E_OOM:return "OOM";case NLSQL_E_LIMIT:return "LIMIT";case NLSQL_E_PARSE:return "PARSE";case NLSQL_E_SCHEMA:return "SCHEMA";case NLSQL_E_POLICY:return "POLICY";case NLSQL_E_UNSUPPORTED:return "UNSUPPORTED";case NLSQL_E_TYPE:return "TYPE";case NLSQL_E_DIALECT:return "DIALECT";default:return "INTERNAL";}}
const char *nlsql_dialect_name(nlsql_dialect d){switch(d){case NLSQL_DIALECT_POSTGRES:return "postgres";case NLSQL_DIALECT_SQLITE:return "sqlite";case NLSQL_DIALECT_DUCKDB:return "duckdb";case NLSQL_DIALECT_MYSQL:return "mysql";case NLSQL_DIALECT_SQLSERVER:return "sqlserver";default:return "unknown";}}

nlsql_status nlsql_context_create(const nlsql_config *in,nlsql_context **out){nlsql_context*c;if(!out)return NLSQL_E_INVALID_ARGUMENT;c=(nlsql_context*)calloc(1,sizeof(*c));if(!c)return NLSQL_E_OOM;c->cfg.limits.max_ir_bytes= in&&in->limits.max_ir_bytes?in->limits.max_ir_bytes:65536u;c->cfg.limits.max_schema_objects=in&&in->limits.max_schema_objects?in->limits.max_schema_objects:4096u;c->cfg.limits.max_sql_bytes=in&&in->limits.max_sql_bytes?in->limits.max_sql_bytes:1048576u;c->cfg.limits.max_nodes=in&&in->limits.max_nodes?in->limits.max_nodes:4096u;c->cfg.limits.max_joins=in&&in->limits.max_joins?in->limits.max_joins:16u;c->cfg.limits.max_selected_fields=in&&in->limits.max_selected_fields?in->limits.max_selected_fields:64u;c->cfg.limits.default_limit=in&&in->limits.default_limit?in->limits.default_limit:100u;c->cfg.limits.max_limit=in&&in->limits.max_limit?in->limits.max_limit:1000u;c->cfg.diagnostic_errors=in?in->diagnostic_errors:0;*out=c;return NLSQL_OK;}
void nlsql_context_destroy(nlsql_context*c){free(c);}

nlsql_status nlsql_schema_builder_create(nlsql_context*c,nlsql_schema_builder**out){nlsql_schema_builder*b;if(!c||!out)return NLSQL_E_INVALID_ARGUMENT;b=(nlsql_schema_builder*)calloc(1,sizeof(*b));if(!b)return NLSQL_E_OOM;b->ctx=c;b->schema=(nlsql_schema*)calloc(1,sizeof(*b->schema));if(!b->schema){free(b);return NLSQL_E_OOM;}b->schema->ctx=c;*out=b;return NLSQL_OK;}
static table_t* table_find(nlsql_schema*s,const char*sc,const char*tn){size_t i;for(i=0;i<s->nt;i++)if(eqs(s->tables[i].schema,sc)&&eqs(s->tables[i].name,tn))return &s->tables[i];return NULL;}
static col_t* col_find(nlsql_schema*s,const char*sc,const char*tn,const char*cn){size_t i;for(i=0;i<s->nc;i++)if(eqs(s->cols[i].schema,sc)&&eqs(s->cols[i].table,tn)&&eqs(s->cols[i].name,cn))return &s->cols[i];return NULL;}
nlsql_status nlsql_schema_builder_add_table(nlsql_schema_builder*b,const char*sc,const char*tn,unsigned fl){if(!b||!ident(sc)||!ident(tn))return NLSQL_E_INVALID_ARGUMENT;if(b->schema->nt>=NLSQL_MAX_TABLES||b->schema->nt+b->schema->nc>=b->ctx->cfg.limits.max_schema_objects||table_find(b->schema,sc,tn))return NLSQL_E_SCHEMA;cp(b->schema->tables[b->schema->nt].schema,NLSQL_NAME,sc);cp(b->schema->tables[b->schema->nt].name,NLSQL_NAME,tn);b->schema->tables[b->schema->nt++].flags=fl;return NLSQL_OK;}
nlsql_status nlsql_schema_builder_add_column(nlsql_schema_builder*b,const char*sc,const char*tn,const char*cn,nlsql_type ty,unsigned fl){if(!b||!ident(sc)||!ident(tn)||!ident(cn)||!table_find(b->schema,sc,tn)||col_find(b->schema,sc,tn,cn)||b->schema->nc>=NLSQL_MAX_COLS)return NLSQL_E_SCHEMA;cp(b->schema->cols[b->schema->nc].schema,NLSQL_NAME,sc);cp(b->schema->cols[b->schema->nc].table,NLSQL_NAME,tn);cp(b->schema->cols[b->schema->nc].name,NLSQL_NAME,cn);b->schema->cols[b->schema->nc].type=ty;b->schema->cols[b->schema->nc++].flags=fl;return NLSQL_OK;}
nlsql_status nlsql_schema_builder_add_foreign_key(nlsql_schema_builder*b,const char*fs,const char*ft,const char*fc,const char*ts,const char*tt,const char*tc){fk_t*f;if(!b||b->schema->nf>=NLSQL_MAX_FKS||!col_find(b->schema,fs,ft,fc)||!col_find(b->schema,ts,tt,tc))return NLSQL_E_SCHEMA;f=&b->schema->fks[b->schema->nf++];cp(f->fs,NLSQL_NAME,fs);cp(f->ft,NLSQL_NAME,ft);cp(f->fc,NLSQL_NAME,fc);cp(f->ts,NLSQL_NAME,ts);cp(f->tt,NLSQL_NAME,tt);cp(f->tc,NLSQL_NAME,tc);return NLSQL_OK;}
nlsql_status nlsql_schema_builder_finalize(nlsql_schema_builder*b,nlsql_schema**out){if(!b||!out)return NLSQL_E_INVALID_ARGUMENT;*out=b->schema;b->schema=NULL;return NLSQL_OK;}
void nlsql_schema_builder_destroy(nlsql_schema_builder*b){if(b){free(b->schema);free(b);}}
void nlsql_schema_destroy(nlsql_schema*s){if(s)free(s);}

nlsql_status nlsql_policy_create(nlsql_context*c,nlsql_policy**out){nlsql_policy*p;if(!c||!out)return NLSQL_E_INVALID_ARGUMENT;p=(nlsql_policy*)calloc(1,sizeof(*p));if(!p)return NLSQL_E_OOM;p->ctx=c;p->max_limit=c->cfg.limits.max_limit;p->max_joins=c->cfg.limits.max_joins;*out=p;return NLSQL_OK;}
nlsql_status nlsql_policy_allow_table(nlsql_policy*p,const char*sc,const char*tn){if(!p||!ident(sc)||!ident(tn)||p->na>=NLSQL_MAX_RULES)return NLSQL_E_INVALID_ARGUMENT;cp(p->allow[p->na].schema,NLSQL_NAME,sc);cp(p->allow[p->na++].table,NLSQL_NAME,tn);return NLSQL_OK;}
nlsql_status nlsql_policy_deny_column(nlsql_policy*p,const char*sc,const char*tn,const char*cn){if(!p||!ident(sc)||!ident(tn)||!ident(cn)||p->nd>=NLSQL_MAX_RULES)return NLSQL_E_INVALID_ARGUMENT;cp(p->deny[p->nd].schema,NLSQL_NAME,sc);cp(p->deny[p->nd].table,NLSQL_NAME,tn);cp(p->deny[p->nd++].col,NLSQL_NAME,cn);return NLSQL_OK;}
nlsql_status nlsql_policy_require_tenant(nlsql_policy*p,const char*sc,const char*tn,const char*cn){if(!p||!ident(sc)||!ident(tn)||!ident(cn)||p->ntenant>=NLSQL_MAX_RULES)return NLSQL_E_INVALID_ARGUMENT;cp(p->tenant[p->ntenant].schema,NLSQL_NAME,sc);cp(p->tenant[p->ntenant].table,NLSQL_NAME,tn);cp(p->tenant[p->ntenant++].col,NLSQL_NAME,cn);return NLSQL_OK;}
nlsql_status nlsql_policy_set_limits(nlsql_policy*p,size_t joins,size_t lim){if(!p||joins==0||lim==0)return NLSQL_E_INVALID_ARGUMENT;p->max_joins=joins;p->max_limit=lim;return NLSQL_OK;}
nlsql_status nlsql_policy_set_runtime_tenant(nlsql_policy*p,const char*n,nlsql_type t){if(!p||!ident(n)||t==NLSQL_TYPE_UNKNOWN)return NLSQL_E_INVALID_ARGUMENT;cp(p->runtime_name,NLSQL_NAME,n);p->runtime_type=t;return NLSQL_OK;}
void nlsql_policy_destroy(nlsql_policy*p){free(p);}

static void skip(parser_t*p){while(p->p<p->n&&isspace((unsigned char)p->s[p->p]))p->p++;}
static node_t* parse_node(parser_t*p){node_t*x;size_t start,i,n;if(p->nodes++>=p->ctx->cfg.limits.max_nodes)return NULL;skip(p);if(p->p>=p->n)return NULL;x=(node_t*)calloc(1,sizeof(*x));if(!x)return NULL;x->off=p->p;if(p->s[p->p]=='('){p->p++;skip(p);while(p->p<p->n&&p->s[p->p]!=')'){if(x->nchild>=NLSQL_MAX_CHILDREN){free(x);return NULL;}x->child[x->nchild++]=parse_node(p);if(!x->child[x->nchild-1]){free(x);return NULL;}skip(p);}if(p->p>=p->n){free(x);return NULL;}p->p++;return x;}start=p->p;while(p->p<p->n&&!isspace((unsigned char)p->s[p->p])&&p->s[p->p]!=')'&&p->s[p->p]!='(')p->p++;n=p->p-start;if(n==0||n>=NLSQL_NAME){free(x);return NULL;}x->atom=(char*)calloc(1,n+1);if(!x->atom){free(x);return NULL;}for(i=0;i<n;i++)x->atom[i]=p->s[start+i];return x;}
static void node_free(node_t*x){size_t i;if(!x)return;for(i=0;i<x->nchild;i++)node_free(x->child[i]);free(x->atom);free(x);}
static int atom(node_t*x,const char*s){return x&&x->nchild==0&&eqs(x->atom,s);}
static int list(node_t*x,const char*s){return x&&x->nchild>0&&atom(x->child[0],s);}
static node_t* find_clause(node_t*q,const char*s){size_t i;for(i=1;i<q->nchild;i++)if(list(q->child[i],s))return q->child[i];return NULL;}
static int parse_source(node_t*x,size_t ti,size_t ai,char*sc,char*tn,char*al){if(!x||x->nchild<=ai||x->child[ti]->nchild!=0||x->child[ai]->nchild!=0)return 0;cp(tn,NLSQL_NAME,x->child[ti]->atom);cp(al,NLSQL_NAME,x->child[ai]->atom);cp(sc,NLSQL_NAME,"public");return ident(tn)&&ident(al);}
static int param_index(nlsql_compile_result*r,const char*n,nlsql_type ty,nlsql_param_source src){size_t i;if(!n)return 0;for(i=0;i<r->nparams;i++)if(eqs(r->params[i].name,n))return (int)i+1;if(r->nparams>=NLSQL_MAX_PARAMS)return 0;cp(r->params[r->nparams].name,NLSQL_NAME,n);r->params[r->nparams].type=ty;r->params[r->nparams].source=src;r->nparams++;return (int)r->nparams;}
static int emit_expr(buf_t*b,node_t*x,source_t*src,size_t ns,const nlsql_schema*schema,nlsql_compile_result*r,nlsql_dialect d){size_t i;col_t*c;char *dot;if(!x||x->nchild==0)return 0;if(atom(x->child[0],"column")&&x->nchild==3){if(x->child[1]->nchild||x->child[2]->nchild||!ident(x->child[1]->atom)||!ident(x->child[2]->atom))return 0;for(i=0;i<ns;i++)if(eqs(src[i].alias,x->child[1]->atom)){c=col_find((nlsql_schema*)schema,src[i].schema,src[i].table,x->child[2]->atom);if(!c)return 0;break;}if(i==ns)return 0;return buf_ident(b,x->child[1]->atom,d)&&buf_ch(b,'.')&&buf_ident(b,x->child[2]->atom,d);}if(atom(x->child[0],"param")&&x->nchild==3){int idx;if(x->child[1]->nchild||x->child[2]->nchild||!ident(x->child[1]->atom))return 0;idx=param_index(r,x->child[1]->atom,NLSQL_TYPE_TEXT,NLSQL_PARAM_USER);if(!idx)return 0;if(d==NLSQL_DIALECT_POSTGRES){char t[32];(void)snprintf(t,sizeof(t),"$%d",idx);return buf_put(b,t);}if(d==NLSQL_DIALECT_SQLSERVER){char t[32];(void)snprintf(t,sizeof(t),"@p%d",idx);return buf_put(b,t);}if(d==NLSQL_DIALECT_SQLITE){char t[32];(void)snprintf(t,sizeof(t),"?%d",idx);return buf_put(b,t);}return buf_ch(b,'?');}if(atom(x->child[0],"ref")&&x->nchild==2&&x->child[1]->nchild==0)return buf_ident(b,x->child[1]->atom,d);if(x->nchild==2&&(atom(x->child[0],"sum")||atom(x->child[0],"avg")||atom(x->child[0],"count")||atom(x->child[0],"min")||atom(x->child[0],"max"))){const char*fn=x->child[0]->atom;if(!buf_put(b,fn)||!buf_ch(b,'(')||!emit_expr(b,x->child[1],src,ns,schema,r,d)||!buf_ch(b,')'))return 0;return 1;}if(x->nchild==3&&(atom(x->child[0],"eq")||atom(x->child[0],"gte")||atom(x->child[0],"gt")||atom(x->child[0],"lte")||atom(x->child[0],"lt")||atom(x->child[0],"neq")||atom(x->child[0],"mul"))){const char*op=atom(x->child[0],"eq")?" = ":atom(x->child[0],"gte")?" >= ":atom(x->child[0],"gt")?" > ":atom(x->child[0],"lte")?" <= ":atom(x->child[0],"lt")?" < ":atom(x->child[0],"neq")?" <> ":" * ";if(!buf_ch(b,'(')||!emit_expr(b,x->child[1],src,ns,schema,r,d)||!buf_put(b,op)||!emit_expr(b,x->child[2],src,ns,schema,r,d)||!buf_ch(b,')'))return 0;return 1;}if(x->nchild==2&&atom(x->child[0],"and")){if(!buf_ch(b,'('))return 0;for(i=1;i<x->nchild;i++){if(i>1&&!buf_put(b," AND "))return 0;if(!emit_expr(b,x->child[i],src,ns,schema,r,d))return 0;}return buf_ch(b,')');}dot=strchr(x->child[0]->atom,'.');(void)dot;return 0;}
static int allowed_table(const nlsql_policy*p,const char*sc,const char*tn){size_t i;if(!p||p->na==0)return 1;for(i=0;i<p->na;i++)if(eqs(p->allow[i].schema,sc)&&eqs(p->allow[i].table,tn))return 1;return 0;}
static int policy_tenant(const nlsql_policy*p,const char*sc,const char*tn,const char**cn){size_t i;for(i=0;i<p->ntenant;i++)if(eqs(p->tenant[i].schema,sc)&&eqs(p->tenant[i].table,tn)){*cn=p->tenant[i].col;return 1;}return 0;}
static int join_allowed(const nlsql_schema*s,const node_t*x,const source_t*a,const source_t*b){size_t i;if(!x||x->nchild!=5||!list(x->child[4],"eq"))return 0;x=x->child[4];if(x->nchild!=3||!list(x->child[1],"column")||!list(x->child[2],"column")||x->child[1]->nchild!=3||x->child[2]->nchild!=3)return 0;for(i=0;i<s->nf;i++){const fk_t*f=&s->fks[i];if(eqs(x->child[1]->child[1]->atom,a->alias)&&eqs(x->child[1]->child[2]->atom,f->fc)&&eqs(x->child[2]->child[1]->atom,b->alias)&&eqs(x->child[2]->child[2]->atom,f->tc)&&eqs(a->schema,f->fs)&&eqs(a->table,f->ft)&&eqs(b->schema,f->ts)&&eqs(b->table,f->tt))return 1;if(eqs(x->child[2]->child[1]->atom,a->alias)&&eqs(x->child[2]->child[2]->atom,f->fc)&&eqs(x->child[1]->child[1]->atom,b->alias)&&eqs(x->child[1]->child[2]->atom,f->tc)&&eqs(a->schema,f->fs)&&eqs(a->table,f->ft)&&eqs(b->schema,f->ts)&&eqs(b->table,f->tt))return 1;}return 0;}
static int emit_param(buf_t*b,int idx,nlsql_dialect d){char t[32];if(d==NLSQL_DIALECT_POSTGRES)(void)snprintf(t,sizeof(t),"$%d",idx);else if(d==NLSQL_DIALECT_SQLSERVER)(void)snprintf(t,sizeof(t),"@p%d",idx);else if(d==NLSQL_DIALECT_SQLITE)(void)snprintf(t,sizeof(t),"?%d",idx);else return buf_ch(b,'?');return buf_put(b,t);}
static int compile_tree(nlsql_context*c,const nlsql_compile_request*req,nlsql_compile_result*r){parser_t p;node_t*root;node_t*from,*sel,*where,*grp,*ord,*lim;source_t src[32];size_t ns=0,i,j;buf_t b;size_t joins=0;int tidx;const char*tc;size_t tenant_count=0;if(!req->ir||!req->schema||!req->policy||strlen(req->ir)>c->cfg.limits.max_ir_bytes)return NLSQL_E_LIMIT;p.s=req->ir;p.n=strlen(req->ir);p.p=0;p.nodes=0;p.ctx=c;root=parse_node(&p);skip(&p);if(!root||p.p!=p.n||!list(root,"nlsql")||root->nchild<3||!atom(root->child[1],"1")||!list(root->child[2],"query")){node_free(root);return NLSQL_E_PARSE;}from=find_clause(root->child[2],"from");sel=find_clause(root->child[2],"select");where=find_clause(root->child[2],"where");grp=find_clause(root->child[2],"group-by");ord=find_clause(root->child[2],"order-by");lim=find_clause(root->child[2],"limit");if(!from||!sel||from->nchild<2||from->nchild>3||sel->nchild<2||sel->nchild>c->cfg.limits.max_selected_fields+1){node_free(root);return NLSQL_E_PARSE;}if(!parse_source(from,1,from->nchild==3?2:1,src[0].schema,src[0].table,src[0].alias)||!table_find((nlsql_schema*)req->schema,src[0].schema,src[0].table)||!allowed_table(req->policy,src[0].schema,src[0].table)){node_free(root);return NLSQL_E_POLICY;}ns=1;for(i=1;i<root->child[2]->nchild;i++){node_t*x=root->child[2]->child[i];if(list(x,"join")){if(x->nchild!=5||joins++>=req->policy->max_joins||!atom(x->child[1],"inner")||!parse_source(x,2,3,src[ns].schema,src[ns].table,src[ns].alias)||!table_find((nlsql_schema*)req->schema,src[ns].schema,src[ns].table)||!allowed_table(req->policy,src[ns].schema,src[ns].table)||!list(x->child[4],"eq")||!join_allowed((nlsql_schema*)req->schema,x,&src[0],&src[ns])){node_free(root);return NLSQL_E_POLICY;}ns++;if(ns>=32){node_free(root);return NLSQL_E_LIMIT;}}}if(!buf_init(&b,c)){node_free(root);return NLSQL_E_OOM;}if(!buf_put(&b,"SELECT ")){free(b.s);node_free(root);return NLSQL_E_OOM;}for(i=1;i<sel->nchild;i++){node_t*f=sel->child[i];if(i>1&&!buf_put(&b,", "))goto fail;if(!f||f->nchild!=3||!list(f,"field")||f->child[2]->nchild||!ident(f->child[2]->atom)||!emit_expr(&b,f->child[1],src,ns,req->schema,r,req->dialect))goto fail;if(!buf_put(&b," AS ")||!buf_ident(&b,f->child[2]->atom,req->dialect))goto fail;}if(!buf_put(&b," FROM ")||!buf_ident(&b,src[0].schema,req->dialect)||!buf_ch(&b,'.')||!buf_ident(&b,src[0].table,req->dialect)||!buf_put(&b," AS ")||!buf_ident(&b,src[0].alias,req->dialect))goto fail;for(i=1;i<ns;i++){node_t*jnode=NULL;for(j=1;j<root->child[2]->nchild;j++)if(list(root->child[2]->child[j],"join")&&eqs(root->child[2]->child[j]->child[3]->atom,src[i].alias)){jnode=root->child[2]->child[j];break;}if(!jnode||!buf_put(&b," INNER JOIN ")||!buf_ident(&b,src[i].schema,req->dialect)||!buf_ch(&b,'.')||!buf_ident(&b,src[i].table,req->dialect)||!buf_put(&b," AS ")||!buf_ident(&b,src[i].alias,req->dialect)||!buf_put(&b," ON ")||!emit_expr(&b,jnode->child[4],src,ns,req->schema,r,req->dialect))goto fail;}if(where){if(!buf_put(&b," WHERE ")||!emit_expr(&b,where->child[1],src,ns,req->schema,r,req->dialect))goto fail;}for(i=0;i<ns;i++)if(policy_tenant(req->policy,src[i].schema,src[i].table,&tc)){if(!buf_put(&b,where?" AND ":" WHERE ")||!buf_ident(&b,src[i].alias,req->dialect)||!buf_ch(&b,'.')||!buf_ident(&b,tc,req->dialect)||!buf_put(&b," = "))goto fail;tenant_count++;tidx=param_index(r,req->policy->runtime_name[0]?req->policy->runtime_name:"tenant_id",req->policy->runtime_type?req->policy->runtime_type:NLSQL_TYPE_UUID,NLSQL_PARAM_POLICY);if(tidx==0)goto fail;if(!emit_param(&b,tidx,req->dialect))goto fail;where=(node_t*)1;}if(grp){if(!buf_put(&b," GROUP BY "))goto fail;for(i=1;i<grp->nchild;i++){if(i>1&&!buf_put(&b,", "))goto fail;if(!emit_expr(&b,grp->child[i],src,ns,req->schema,r,req->dialect))goto fail;}}if(ord){if(ord->nchild!=3||!buf_put(&b," ORDER BY ")||!emit_expr(&b,ord->child[1],src,ns,req->schema,r,req->dialect)||!buf_put(&b,atom(ord->child[2],"desc")?" DESC":" ASC"))goto fail;}if(lim){unsigned long v;if(lim->nchild!=2||lim->child[1]->nchild||!lim->child[1]->atom||!isdigit((unsigned char)lim->child[1]->atom[0])){goto fail;}v=strtoul(lim->child[1]->atom,NULL,10);if(v==0||v>req->policy->max_limit)goto fail;if(!buf_put(&b," LIMIT "))goto fail;{char t[32];(void)snprintf(t,sizeof(t),"%lu",v);if(!buf_put(&b,t))goto fail;}}else{char t[32];if(!buf_put(&b," LIMIT "))goto fail;(void)snprintf(t,sizeof(t),"%lu",(unsigned long)c->cfg.limits.default_limit);if(!buf_put(&b,t))goto fail;}r->sql=b.s;r->sql_len=b.n;r->complexity=(unsigned)(1+joins+sel->nchild+tenant_count);r->risk=tenant_count?NLSQL_RISK_LOW:NLSQL_RISK_MODERATE;r->status=NLSQL_OK;{char m[512];(void)snprintf(m,sizeof(m),"version=1\ndialect=%s\nparameters=%lu\ntenant_predicates=%lu\ncomplexity=%u\nrisk=%s\n",nlsql_dialect_name(req->dialect),(unsigned long)r->nparams,tenant_count,r->complexity,r->risk==NLSQL_RISK_LOW?"LOW":"MODERATE");r->manifest=(char*)calloc(1,strlen(m)+1u);if(r->manifest)memcpy(r->manifest,m,strlen(m));}node_free(root);return r->manifest?NLSQL_OK:NLSQL_E_OOM;fail:free(b.s);node_free(root);if(r->status==NLSQL_OK)r->status=NLSQL_E_PARSE;return r->status;}

nlsql_status nlsql_compile_ir(nlsql_context*c,const nlsql_compile_request*req,nlsql_compile_result**out){nlsql_compile_result*r;size_t n;if(!c||!req||!out)return NLSQL_E_INVALID_ARGUMENT;r=(nlsql_compile_result*)calloc(1,sizeof(*r));if(!r)return NLSQL_E_OOM;r->error=(char*)calloc(1,512);if(!r->error){free(r);return NLSQL_E_OOM;}n=req->ir?strlen(req->ir):0u;r->ir=(char*)calloc(1,n+1u);if(!r->ir){nlsql_compile_result_destroy(r);return NLSQL_E_OOM;}if(req->ir)memcpy(r->ir,req->ir,n);r->status=compile_tree(c,req,r);if(r->status!=NLSQL_OK&&r->error[0]==0)cp(r->error,512,nlsql_status_name(r->status));*out=r;return r->status;}
nlsql_status nlsql_compile_question(nlsql_context*c,const nlsql_question_request*req,nlsql_compile_result**out){(void)c;(void)req;(void)out;return NLSQL_E_UNSUPPORTED;}
void nlsql_compile_result_destroy(nlsql_compile_result*r){if(r){free(r->sql);free(r->ir);free(r->manifest);free(r->error);free(r);}}
nlsql_sql_view nlsql_result_sql(const nlsql_compile_result*r){nlsql_sql_view v={NULL,0};if(r){v.sql=r->sql;v.length=r->sql_len;}return v;}
const char*nlsql_result_canonical_ir(const nlsql_compile_result*r){return r?r->ir:NULL;}
const char*nlsql_result_manifest(const nlsql_compile_result*r){return r?r->manifest:NULL;}
const char*nlsql_result_error(const nlsql_compile_result*r){return r?r->error:NULL;}
nlsql_status nlsql_result_status(const nlsql_compile_result*r){return r?r->status:NLSQL_E_INVALID_ARGUMENT;}
size_t nlsql_result_param_count(const nlsql_compile_result*r){return r?r->nparams:0u;}
nlsql_param_view nlsql_result_param(const nlsql_compile_result*r,size_t i){nlsql_param_view v={0,NULL,NLSQL_TYPE_UNKNOWN,NLSQL_PARAM_USER,0};if(r&&i<r->nparams){v.position=i+1u;v.name=r->params[i].name;v.type=r->params[i].type;v.source=r->params[i].source;v.runtime_required=(r->params[i].source!=NLSQL_PARAM_TRUSTED);}return v;}
nlsql_risk nlsql_result_risk(const nlsql_compile_result*r){return r?r->risk:NLSQL_RISK_DENIED;}
unsigned nlsql_result_complexity(const nlsql_compile_result*r){return r?r->complexity:0u;}
